import java.util.ArrayList;
import java.util.List;

public class Main {
    public static List<List<Integer>> calculateMovingAverages(List<List<Integer>> data, int windowSize) {
        List<List<Integer>> movingAverages = new ArrayList<>();
        for (List<Integer> row : data) {
            List<Integer> averages = new ArrayList<>();
            for (int i = 0; i < row.size(); i++) {
                int start = Math.max(0, i - windowSize + 1);
                int end = i + 1;
                int sum = 0;
                for (int j = start; j < end; j++) {
                    sum += row.get(j);
                }
                averages.add(sum / (end - start));
            }
            movingAverages.add(averages);
        }
        return movingAverages;
    }

    public static void main(String[] args) {
        List<List<Integer>> data = new ArrayList<>();
        data.add(new ArrayList<>(List.of(1, 2, 3, 4, 5)));
        data.add(new ArrayList<>(List.of(6, 7, 8, 9, 10)));
        data.add(new ArrayList<>(List.of(11, 12, 13, 14, 15)));
        data.add(new ArrayList<>(List.of(16, 17, 18, 19, 20)));
        data.add(new ArrayList<>(List.of(21, 22, 23, 24, 25)));

        int windowSize = 3;
        List<List<Integer>> movingAverages = calculateMovingAverages(data, windowSize);

        for (List<Integer> row : movingAverages) {
            System.out.println(row);
        }
    }
}
```

```java
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<List<Object>> data = new ArrayList<>();
        data.add(List.of(1, 6, 11));
        data.add(List.of(2, 7, 12));
        data.add(List.of(3, 8, 13));
        data.add(List.of(4, 9, 14));
        data.add(List.of(5, 10, 15));

        int outputListSize = 3;
        List<List<Object>> outputData = new ArrayList<>();

        for (int i = 0; i < data.size(); i++) {
            List<Object> row = new ArrayList<>();
            for (int j = 0; j < outputListSize; j++) {
                row.add(data.get((i * outputListSize) + j).get(0));
            }
            outputData.add(row);
        }

        System.out.println(outputData);
    }
}
